class BasicMaterialCommonPanel extends Panel {
    constructor(mesh) {
        super();

        this.mesh = mesh;

        this.materials = Array.isArray(this.mesh.material) ? this.mesh.material : [this.mesh.material];
        this.material = this.materials[0];

        this.initPanel();
    }

    initPanel() {
        const materials = this.materials;
        const material = this.material;

        const items = [
            {
                type: 'divider'
            },
            {
                type: 'color',
                name: 'Color',
                value: material.color,
                callback: value => {
                    materials.forEach(material => material.color.copy(value));
                }
            },
            {
                type: 'list',
                name: 'Wire',
                list: WireframeOptions,
                value: getKeyByValue(WireframeOptions, material.wireframe),
                callback: value => {
                    materials.forEach(material => material.wireframe = WireframeOptions.get(value));
                }
            },
            {
                type: 'list',
                name: 'Fog',
                list: FogOptions,
                value: getKeyByValue(FogOptions, material.fog),
                callback: value => {
                    materials.forEach(material => material.fog = FogOptions.get(value));
                }
            },
            {
                type: 'list',
                name: 'Tone',
                list: ToneMappedOptions,
                value: getKeyByValue(ToneMappedOptions, material.toneMapped),
                callback: value => {
                    materials.forEach(material => material.toneMapped = ToneMappedOptions.get(value));
                }
            }
        ];

        items.forEach(data => {
            this.add(new PanelItem(data));
        });
    }
}

/**
 * @author pschroen / https://ufo.ai/
 */


class MeshHelperPanel extends Panel {
    constructor(mesh, ui) {
        super();

        this.mesh = mesh;
        this.ui = ui;

        this.initPanel();
    }

    initPanel() {
        const mesh = this.mesh;
        const ui = this.ui;

        let point;

        if (ui.constructor.points) {
            point = ui.constructor.getPoint(mesh);
        }

        // Defaults
        if (mesh.userData.normals === undefined) {
            mesh.userData.normals = false;
        }

        if (mesh.userData.tangents === undefined) {
            mesh.userData.tangents = false;
        }

        if (mesh.userData.uv === undefined) {
            mesh.userData.uv = false;
        }

        const items = [
            {
                type: 'divider'
            },
            {
                type: 'list',
                name: 'Normals',
                list: NormalsHelperOptions,
                value: getKeyByValue(NormalsHelperOptions, mesh.userData.normals),
                callback: value => {
                    mesh.userData.normals = NormalsHelperOptions.get(value);

                    if (point) {
                        point.toggleNormalsHelper(mesh.userData.normals);
                    }
                }
            }
        ];

        if (mesh.geometry.index) {
            items.push(
                {
                    type: 'list',
                    name: 'Tangents',
                    list: TangentsHelperOptions,
                    value: getKeyByValue(TangentsHelperOptions, mesh.userData.tangents),
                    callback: value => {
                        mesh.userData.tangents = TangentsHelperOptions.get(value);

                        if (point) {
                            point.toggleTangentsHelper(mesh.userData.tangents);
                        }
                    }
                }
            );
        }

        if (ui.constructor.uvHelper) {
            items.push(
                {
                    type: 'list',
                    name: 'UV',
                    list: UVHelperOptions,
                    value: getKeyByValue(UVHelperOptions, mesh.userData.uv),
                    callback: value => {
                        mesh.userData.uv = UVHelperOptions.get(value);
                        point.toggleUVHelper(mesh.userData.uv);
                    }
                }
                // TODO: Texture thumbnails
            );
        }

        items.forEach(data => {
            this.add(new PanelItem(data));
        });
    }
}

/**
 * @author pschroen / https://ufo.ai/
 */


class OimoPhysicsPanel extends Panel {
    constructor(mesh, ui) {
        super();

        this.mesh = mesh;
        this.ui = ui;

        this.initPanel();
    }

    initPanel() {
        const ui = this.ui;

        const { physics } = ui.constructor;

        let object = this.mesh;

        if (object.parent && object.parent.isGroup) {
            object = object.parent;
        }

        const angularVelocity = physics.getAngularVelocity(object);

        const items = [
            {
                type: 'divider'
            },
            {
                type: 'slider',
                name: 'Gravity',
                min: -1,
                max: 1,
                step: 0.01,
                value: physics.getGravityScale(object),
                callback: value => {
                    physics.setGravityScale(object, value);
                }
            },
            {
                type: 'slider',
                name: 'Rotate X',
                min: 0,
                max: 16,
                step: 1,
                value: angularVelocity.x,
                callback: value => {
                    angularVelocity.setX(value);
                    physics.setAngularVelocity(object, angularVelocity);
                }
            },
            {
                type: 'slider',
                name: 'Rotate Y',
                min: 0,
                max: 16,
                step: 1,
                value: angularVelocity.y,
                callback: value => {
                    angularVelocity.setY(value);
                    physics.setAngularVelocity(object, angularVelocity);
                }
            },
            {
                type: 'slider',
                name: 'Rotate Z',
                min: 0,
                max: 16,
                step: 1,
                value: angularVelocity.z,
                callback: value => {
                    angularVelocity.setZ(value);
                    physics.setAngularVelocity(object, angularVelocity);
                }
            }
        ];

        items.forEach(data => {
            this.add(new PanelItem(data));
        });
    }
}

/**
 * @author pschroen / https://ufo.ai/
 */


let renderer;
let camera;
let screen;
let ball;

function getThumbnail(texture, size = 200) {
    if (!renderer) {
        renderer = new WebGLRenderer({
            alpha: true,
            antialias: true,
            depth: false
        });

        camera = new OrthographicCamera(-1, 1, 1, -1, 0, 1);
        camera.position.set(0, 0, 1);
    }

    if (!screen) {
        screen = new Mesh(
            getFullscreenTriangle(),
            new MeshBasicMaterial({ transparent: true })
        );
        screen.frustumCulled = false;
    }

    screen.material.map = texture;
    screen.material.needsUpdate = true;

    renderer.setSize(size, size);
    renderer.clear();
    renderer.render(screen, camera);

    const image = new Image();
    image.src = renderer.domElement.toDataURL();

    return image;
}

function getBallThumbnail(texture, size = 200) {
    if (!renderer) {
        renderer = new WebGLRenderer({
            alpha: true,
            antialias: true,
            depth: false
        });

        camera = new OrthographicCamera(-1, 1, 1, -1, 0, 1);
        camera.position.set(0, 0, 1);
    }

    if (!ball) {
        ball = new Mesh(
            getSphericalCube(),
            Array.from({ length: 6 }, () => new MeshBasicMaterial({ transparent: true }))
        );
        ball.frustumCulled = false;
    }

    if (Array.isArray(texture)) {
        for (let i = 0, l = ball.material.length; i < l; i++) {
            ball.material[i].map = texture[i];
            ball.material[i].needsUpdate = true;
        }
    } else {
        for (let i = 0, l = ball.material.length; i < l; i++) {
            ball.material[i].envMap = texture;
            ball.material[i].needsUpdate = true;
        }
    }

    renderer.setSize(size, size);
    renderer.clear();
    renderer.render(ball, camera);

    const image = new Image();
    image.src = renderer.domElement.toDataURL();

    return image;
}

/**
 * @author pschroen / https://ufo.ai/
 */


class MapPanel extends Panel {
    constructor(mesh, ui, key, mapping = UVMapping, colorSpace = NoColorSpace) {
        super();

        this.mesh = mesh;
        this.ui = ui;
        this.key = key;
        this.mapping = mapping;
        this.colorSpace = colorSpace;

        this.materials = Array.isArray(this.mesh.material) ? this.mesh.material : [this.mesh.material];
        this.material = this.materials[0];
        this.supported = false;
        this.initialized = false;

        this.initPanel();
    }

    initPanel() {
        if (Array.isArray(this.mesh.material)) {
            this.updateOptions();

            const items = [
                {
                    type: 'divider'
                },
                {
                    type: 'list',
                    name: 'Index',
                    list: this.options,
                    value: getKeyByValue(this.options, 0),
                    callback: (value, item) => {
                        const index = this.options.get(value);

                        const indexPanel = new Panel();
                        indexPanel.animateIn(true);

                        this.initThumbnailPanel(index, indexPanel, item);

                        item.setContent(indexPanel);
                    }
                }
            ];

            items.forEach(data => {
                this.add(new PanelItem(data));
            });
        } else {
            this.initThumbnailPanel(0, this);
        }
    }

    initThumbnailPanel(index, panel, parent) {
        this.update(index);

        const mesh = this.mesh;
        const ui = this.ui;
        const key = this.key;

        const material = this.material;

        let point;

        if (ui.constructor.points) {
            point = ui.constructor.getPoint(mesh);
        }

        const items = [
            {
                type: 'divider'
            },
            {
                type: 'thumbnail',
                name: 'Map',
                data: this.supported ? this.textures[index] : {},
                value: this.supported ? this.thumbnails[index] : null,
                callback: (value, item) => {
                    const data = item.data;

                    const mapItems = [];

                    if (this.initialized) {
                        if (data.isTexture && data.userData.uv && !mesh.userData.uv) {
                            mesh.userData.uv = true;

                            if (point) {
                                point.toggleUVHelper(true);
                            }
                        }

                        if (point && point.uvTexture) {
                            if (value) {
                                if (material[key] && data.isTexture && !data.userData.uv) {
                                    mesh.userData.uv = false;
                                    point.toggleUVHelper(false);
                                }
                            } else if (material[key]) {
                                mesh.userData.uv = false;
                                point.toggleUVHelper(false);

                                if (material[key] && material[key].userData.thumbnail) {
                                    item.setData(material[key]);
                                    item.setValue(material[key].userData.thumbnail);
                                    return;
                                }
                            }
                        } else if (value) {
                            if (this.supported) {
                                material[key].dispose();
                                material[key] = value instanceof Texture ? value : new Texture(value);
                                material[key].mapping = data.mapping;
                                material[key].colorSpace = value instanceof Texture ? value.colorSpace : this.colorSpace;
                                material[key].anisotropy = data.anisotropy;
                                material[key].wrapS = data.wrapS;
                                material[key].wrapT = data.wrapT;
                                material[key].repeat.copy(data.repeat);
                            } else {
                                material[key] = value instanceof Texture ? value : new Texture(value);
                                material[key].mapping = this.mapping;
                                material[key].colorSpace = value instanceof Texture ? value.colorSpace : this.colorSpace;
                            }

                            if (key === 'envMap') {
                                material[key].userData.thumbnail = getBallThumbnail(material[key]);
                            } else if (material[key].source.data instanceof Image) {
                                material[key].userData.thumbnail = material[key].source.data;
                            } else {
                                material[key].userData.thumbnail = getThumbnail(material[key]);
                            }

                            material[key].needsUpdate = true;
                            material.needsUpdate = true;
                        } else if (this.supported) {
                            material[key].dispose();
                            material[key] = null;
                            material.needsUpdate = true;
                        }

                        this.update(index);

                        if (parent) {
                            this.updateOptions();

                            parent.setList(this.options);
                        }

                        item.setData(this.supported ? material[key] : {});
                        item.setValue(this.supported ? material[key].userData.thumbnail : null);
                    }

                    if (this.supported && !(key === 'envMap' && material.isMeshStandardMaterial)) {
                        if (material[key].mapping !== UVMapping) {
                            mapItems.push(
                                {
                                    type: 'spacer'
                                },
                                {
                                    type: 'list',
                                    name: 'Mapping',
                                    list: RefractionMappingOptions,
                                    value: getKeyByValue(RefractionMappingOptions, material[key].mapping),
                                    callback: value => {
                                        if (this.initialized) {
                                            material[key].mapping = RefractionMappingOptions.get(value);
                                            material[key].needsUpdate = true;
                                            material.needsUpdate = true;
                                        }
                                    }
                                }
                            );
                        } else {
                            mapItems.push(
                                {
                                    type: 'spacer'
                                },
                                {
                                    type: 'list',
                                    name: 'Color Space',
                                    list: ColorSpaceOptions,
                                    value: getKeyByValue(ColorSpaceOptions, material[key].colorSpace),
                                    callback: value => {
                                        if (this.initialized) {
                                            material[key].colorSpace = ColorSpaceOptions.get(value);
                                            material[key].needsUpdate = true;
                                        }
                                    }
                                },
                                {
                                    type: 'slider',
                                    name: 'Anisotropy',
                                    min: 1,
                                    max: 16,
                                    step: 1,
                                    value: material[key].anisotropy,
                                    callback: value => {
                                        if (this.initialized) {
                                            material[key].anisotropy = value;
                                            material[key].needsUpdate = true;
                                        }
                                    }
                                },
                                {
                                    type: 'list',
                                    name: 'Wrap',
                                    list: WrapOptions,
                                    value: getKeyByValue(WrapOptions, material[key].wrapS),
                                    callback: value => {
                                        if (this.initialized) {
                                            const wrapping = WrapOptions.get(value);

                                            material[key].wrapS = wrapping;
                                            material[key].wrapT = wrapping;
                                            material[key].needsUpdate = true;
                                        }
                                    }
                                },
                                {
                                    type: 'slider',
                                    name: 'U',
                                    min: 1,
                                    max: 16,
                                    step: 1,
                                    value: material[key].repeat.x,
                                    callback: value => {
                                        if (this.initialized) {
                                            material[key].repeat.setX(value);
                                        }
                                    }
                                },
                                {
                                    type: 'slider',
                                    name: 'V',
                                    min: 1,
                                    max: 16,
                                    step: 1,
                                    value: material[key].repeat.y,
                                    callback: value => {
                                        if (this.initialized) {
                                            material[key].repeat.setY(value);
                                        }
                                    }
                                }
                            );
                        }
                    }

                    const mapPanel = new Panel();
                    mapPanel.animateIn(true);

                    mapItems.forEach(data => {
                        mapPanel.add(new PanelItem(data));
                    });

                    item.setContent(mapPanel);

                    if (!this.initialized) {
                        this.initialized = true;
                    }
                }
            }
        ];

        items.forEach(data => {
            panel.add(new PanelItem(data));
        });
    }

    update(index) {
        this.materials = Array.isArray(this.mesh.material) ? this.mesh.material : [this.mesh.material];
        this.material = this.materials[index];
        this.textures = this.materials.map(material => material[this.key]);
        this.thumbnails = this.textures.map(texture => texture && texture.userData.thumbnail);

        const texture = this.textures[index];

        this.supported = !!(texture && texture.isTexture && !texture.isRenderTargetTexture && !texture.isCubeTexture);
        this.initialized = false;
    }

    updateOptions() {
        this.options = new Map(this.materials.map((material, i) => [material.name || (i + 1).toString(), i]));
    }
}

