class DetailsTitle extends Interface {
    constructor(title) {
        super('.title', 'h1');

        this.title = title;

        this.letters = [];

        this.init();
        this.initText();
    }

    init() {
        this.css({
            width: 'fit-content',
            whiteSpace: 'nowrap'
        });
    }

    initText() {
        const split = this.title.split('');

        split.forEach(string => {
            if (string === ' ') {
                string = '&nbsp';
            }

            const letter = new Interface(null, 'span');
            letter.css({ display: 'inline-block' });
            letter.html(string);
            this.add(letter);

            this.letters.push(letter);
        });
    }

    // Public methods

    setTitle(title) {
        this.title = title;
        this.letters = [];

        this.empty();
        this.initText();
        this.animateIn();
    }

    animateIn() {
        if (!this.letters) {
            return;
        }

        shuffle(this.letters);

        const letters = this.letters.filter(letter => letter.text() !== '_').slice(0, 2);

        letters.forEach((letter, i) => {
            letter.clearTween().css({ opacity: 0 }).tween({ opacity: 1 }, 2000, 'easeOutCubic', 100 + i * 15);
        });
    }
}

