/**
 * @author pschroen / https://ufo.ai/
 */


class Thumbnail extends Interface {
    constructor(data) {
        super('.thumbnail');

        const defaults = {
            width: 150,
            height: 100,
            snapMargin: 20,
            position: 'tl',
            noCanvas: false
        };

        if (data.image) {
            data = Object.assign(defaults, data);

            this.image = data.image;
            this.width = data.width;
            this.height = data.height;
            this.snapMargin = data.snapMargin;
            this.position = data.position;
            this.noCanvas = data.noCanvas;
            this.callback = data.callback;
        } else {
            this.image = data;
            this.width = defaults.width;
            this.height = defaults.height;
            this.snapMargin = defaults.snapMargin;
            this.position = defaults.position;
            this.noCanvas = defaults.noCanvas;
        }

        this.bounds = null;
        this.origin = new Vector2();
        this.mouse = new Vector2();
        this.delta = new Vector2();
        this.lastTime = 0;
        this.lastMouse = new Vector2();
        this.lastOrigin = new Vector2();
        this.snapPosition = new Vector2();
        this.snapTarget = new Vector2();
        this.windowSnapMargin = this.snapMargin;
        this.snappedTop = this.position === 'tl' || this.position === 'tr';
        this.snappedRight = this.position === 'br' || this.position === 'tr';
        this.snappedBottom = this.position === 'bl' || this.position === 'br';
        this.snappedLeft = this.position === 'tl' || this.position === 'bl';
        this.snapped = this.snappedTop || this.snappedRight || this.snappedBottom || this.snappedLeft;

        this.init();

        if (!this.noCanvas) {
            this.initCanvas();
        }

        this.setThumbnail(this.image, this.noCanvas);

        this.addListeners();
    }

    init() {
        this.css({
            position: 'absolute',
            left: this.snapMargin,
            top: this.snapMargin,
            boxSizing: 'border-box',
            width: this.width,
            height: this.height,
            border: '1px solid var(--ui-color-divider-line)',
            cursor: 'move',
            pointerEvents: 'none',
            webkitUserSelect: 'none',
            userSelect: 'none',
            opacity: 0
        });
    }

    initCanvas() {
        this.canvas = new Interface(null, 'canvas');
        this.canvas.css({
            position: 'absolute',
            left: 0,
            top: 0,
            width: '100%',
            height: '100%',
            objectFit: 'cover'
        });
        this.add(this.canvas);

        this.context = this.canvas.element.getContext('2d');
    }

    addListeners() {
        this.element.addEventListener('pointerdown', this.onPointerDown);
        this.element.addEventListener('dragover', this.onDragOver);
        this.element.addEventListener('drop', this.onDrop);
    }

    removeListeners() {
        this.element.removeEventListener('pointerdown', this.onPointerDown);
        this.element.removeEventListener('dragover', this.onDragOver);
        this.element.removeEventListener('drop', this.onDrop);
    }

    async loadFiles(files) {
        const data = await loadFiles(files);

        if (data.length) {
            const { image } = data[0];

            if (image instanceof Image) {
                this.setThumbnail(image, true);
            }
        }
    }

    // Event handlers

    onPointerDown = e => {
        this.bounds = this.element.getBoundingClientRect();
        this.lastTime = performance.now();
        this.lastMouse.set(e.clientX, e.clientY);
        this.lastOrigin.copy(this.bounds);

        this.onPointerMove(e);

        window.addEventListener('pointermove', this.onPointerMove);
        window.addEventListener('pointerup', this.onPointerUp);
    };

    onPointerMove = ({ clientX, clientY }) => {
        const event = {
            x: clientX,
            y: clientY
        };

        this.mouse.copy(event);
        this.delta.subVectors(this.mouse, this.lastMouse);

        if (this.delta.length()) {
            this.origin.addVectors(this.lastOrigin, this.delta);
            this.snap();
        }
    };

    onPointerUp = () => {
        window.removeEventListener('pointermove', this.onPointerMove);
        window.removeEventListener('pointerup', this.onPointerUp);

        if (performance.now() - this.lastTime > 250 || this.delta.length() > 50) {
            return;
        }

        this.events.emit('click', { target: this });
    };

    onDragOver = e => {
        e.preventDefault();
        e.dataTransfer.dropEffect = 'copy';
    };

    onDrop = e => {
        e.preventDefault();

        this.loadFiles(e.dataTransfer.files);
    };

    // Public methods

    setThumbnail(image, noCanvas) {
        this.image = image;

        if (noCanvas) {
            if (!this.wrapper) {
                this.wrapper = new Interface('.wrapper');
                this.add(this.wrapper);
            }

            const content = new Interface(this.image);
            content.css({
                position: 'absolute',
                left: 0,
                top: 0,
                width: '100%',
                height: '100%',
                objectFit: 'cover'
            });

            const oldWrapper = this.wrapper;

            const newWrapper = this.wrapper.clone();
            newWrapper.add(content);

            this.replace(oldWrapper, newWrapper);
            this.wrapper = newWrapper;

            oldWrapper.destroy();

            if (this.canvas) {
                this.canvas = this.canvas.destroy();
                this.context = null;
            }
        } else {
            this.update();
        }

        this.events.emit('update', { image: this.image, target: this });

        if (this.callback) {
            this.callback(this.image, this);
        }
    }

    resize(width, height, dpr, breakpoint) {
        if (width < breakpoint) {
            this.windowSnapMargin = this.snapMargin - 10;
        } else {
            this.windowSnapMargin = this.snapMargin;
        }

        if (this.snapped) {
            if (this.snappedTop) {
                this.css({ top: this.windowSnapMargin });
            }

            if (this.snappedRight) {
                this.css({ left: width - this.width - this.windowSnapMargin });
            }

            if (this.snappedBottom) {
                this.css({ top: height - this.height - this.windowSnapMargin });
            }

            if (this.snappedLeft) {
                this.css({ left: this.windowSnapMargin });
            }
        }

        if (this.canvas) {
            this.canvas.element.width = Math.round(this.width * dpr);
            this.canvas.element.height = Math.round(this.height * dpr);

            this.update();
        }
    }

    update() {
        if (this.canvas && this.image) {
            // Draws from a canvas are faster
            this.context.drawImage(this.image, 0, 0, this.canvas.element.width, this.canvas.element.height);
        }
    }

    animateIn(delay) {
        this.clearTween();
        this.css({ opacity: 0 }).tween({ opacity: 1 }, 700, 'easeOutCubic', delay, () => {
            this.css({ pointerEvents: 'auto' });
        });
    }

    animateOut(delay) {
        this.clearTween();
        this.css({ pointerEvents: 'none' });
        this.tween({ opacity: 0 }, 700, 'easeOutCubic', delay);
    }

    snap() {
        let snappedTop = false;
        let snappedRight = false;
        let snappedBottom = false;
        let snappedLeft = false;

        this.snapPosition.copy(this.origin);
        this.snapTarget.copy(this.snapPosition);

        // Top
        if (this.snapTarget.y <= this.windowSnapMargin + 10) {
            this.snapTarget.y = this.windowSnapMargin;
            snappedTop = true;
        }

        // Right
        if (this.snapTarget.x >= window.innerWidth - this.width - this.windowSnapMargin - 10) {
            this.snapTarget.x = window.innerWidth - this.width - this.windowSnapMargin;
            snappedRight = true;
        }

        // Bottom
        if (this.snapTarget.y >= window.innerHeight - this.height - this.windowSnapMargin - 10) {
            this.snapTarget.y = window.innerHeight - this.height - this.windowSnapMargin;
            snappedBottom = true;
        }

        // Left
        if (this.snapTarget.x <= this.windowSnapMargin + 10) {
            this.snapTarget.x = this.windowSnapMargin;
            snappedLeft = true;
        }

        this.snapPosition.sub(this.snapTarget);
        this.origin.sub(this.snapPosition); // Subtract delta

        this.css({ left: this.origin.x, top: this.origin.y });

        this.snappedTop = snappedTop;
        this.snappedRight = snappedRight;
        this.snappedBottom = snappedBottom;
        this.snappedLeft = snappedLeft;
        this.snapped = this.snappedTop || this.snappedRight || this.snappedBottom || this.snappedLeft;
    }

    destroy() {
        this.removeListeners();

        return super.destroy();
    }
}

/**
 * @author pschroen / https://ufo.ai/
 */


class DetailsButton extends Interface {
    constructor() {
        super('.button');

        const size = 20;

        this.width = size;
        this.height = size;
        this.x = size / 2;
        this.y = size / 2;
        this.radius = size * 0.4;
        this.hoverRadius = size * 0.3;
        this.openRadius = size * 0.2;
        this.startAngle = 0;
        this.endAngle = Math.PI * 2;
        this.isOpen = false;
        this.animatedIn = false;
        this.hoveredIn = false;
        this.needsUpdate = false;

        this.props = {
            radius: this.radius
        };

        this.init();
        this.initCanvas();

        this.addListeners();
    }

    init() {
        this.css({
            position: 'relative',
            width: this.width + 40,
            height: this.height + 20,
            cursor: 'pointer',
            pointerEvents: 'auto',
            webkitUserSelect: 'none',
            userSelect: 'none',
            opacity: 0
        });
    }

    initCanvas() {
        this.canvas = new Interface(null, 'canvas');
        this.canvas.css({
            position: 'absolute',
            left: 10,
            top: 10
        });
        this.context = this.canvas.element.getContext('2d');
        this.add(this.canvas);
    }

    addListeners() {
        this.element.addEventListener('mouseenter', this.onHover);
        this.element.addEventListener('mouseleave', this.onHover);
        this.element.addEventListener('click', this.onClick);
    }

    removeListeners() {
        this.element.removeEventListener('mouseenter', this.onHover);
        this.element.removeEventListener('mouseleave', this.onHover);
        this.element.removeEventListener('click', this.onClick);
    }

    // Event handlers

    onHover = e => {
        if (!this.animatedIn) {
            return;
        }

        clearTween(this.props);

        this.needsUpdate = true;

        if (this.isOpen) {
            if (e.type === 'mouseenter') {
                this.hoveredIn = true;

                tween(this.props, { radius: this.hoverRadius }, 275, 'easeInOutCubic', () => {
                    this.needsUpdate = false;
                });
            } else {
                this.hoveredIn = false;

                tween(this.props, { radius: this.openRadius }, 275, 'easeInOutCubic', () => {
                    this.needsUpdate = false;
                });
            }
        } else {
            if (e.type === 'mouseenter') {
                this.hoveredIn = true;

                const start = () => {
                    tween(this.props, { radius: this.hoverRadius }, 800, 'easeOutQuart', () => {
                        tween(this.props, { radius: this.radius, spring: 1, damping: 0.5 }, 800, 'easeOutElastic', 500, () => {
                            if (this.hoveredIn) {
                                start();
                            } else {
                                this.needsUpdate = false;
                            }
                        });
                    });
                };

                start();
            } else {
                this.hoveredIn = false;

                tween(this.props, { radius: this.radius, spring: 1, damping: 0.5 }, 800, 'easeOutElastic', 200, () => {
                    this.needsUpdate = false;
                });
            }
        }

        this.events.emit('hover', e, { target: this });
    };

    onClick = e => {
        this.events.emit('click', e, { target: this });
    };

    // Public methods

    setData(data, fast) {
        if (!data) {
            return;
        }

        if (!this.container) {
            this.container = new Interface('.number');
            this.container.css({
                position: 'absolute',
                left: 34,
                top: 12,
                width: 'max-content',
                fontVariantNumeric: 'tabular-nums',
                letterSpacing: 'var(--ui-title-letter-spacing)'
            });
            this.add(this.container);
        }

        if (data.number) {
            if (!this.number) {
                this.number = new Interface('.number');
                this.number.css({
                    cssFloat: 'left'
                });
                this.number.text(data.number);
                this.container.add(this.number);
            }
        }

        if (data.total) {
            if (!this.total) {
                this.total = new Interface('.total');
                this.total.css({
                    cssFloat: 'left',
                    marginLeft: 1,
                    color: 'var(--ui-secondary-color)'
                });
                this.container.add(this.total);
            }

            this.total.text(`/${data.total}`);
        }

        if (String(data.number) === this.number.text()) {
            return;
        }

        if (fast) {
            this.number.text(data.number);
        } else {
            this.number.tween({ y: -10, opacity: 0 }, 300, 'easeInSine', () => {
                this.number.text(data.number);
                this.number.css({ y: 10 }).tween({ y: 0, opacity: 1 }, 1000, 'easeOutCubic');
            });
        }
    }

    resize() {
        const dpr = 2; // Always 2

        this.canvas.element.width = Math.round(this.width * dpr);
        this.canvas.element.height = Math.round(this.height * dpr);
        this.canvas.element.style.width = `${this.width}px`;
        this.canvas.element.style.height = `${this.height}px`;
        this.context.scale(dpr, dpr);

        // Context properties need to be reassigned after resize
        this.context.lineWidth = 1.5;
        this.context.strokeStyle = Stage.rootStyle.getPropertyValue('--ui-color').trim();

        this.update();
    }

    update() {
        this.context.clearRect(0, 0, this.canvas.element.width, this.canvas.element.height);
        this.context.beginPath();
        this.context.arc(this.x, this.y, this.props.radius, this.startAngle, this.endAngle);
        this.context.stroke();
    }

    open() {
        this.isOpen = true;

        clearTween(this.props);

        this.needsUpdate = true;

        tween(this.props, { radius: this.openRadius }, 400, 'easeOutCubic', () => {
            this.needsUpdate = false;
        });
    }

    close() {
        this.isOpen = false;

        clearTween(this.props);

        this.needsUpdate = true;

        tween(this.props, { radius: this.radius }, 400, 'easeOutCubic', () => {
            this.needsUpdate = false;
        });
    }

    animateIn() {
        clearTween(this.props);

        this.props.radius = 0;

        this.animatedIn = false;
        this.needsUpdate = true;

        tween(this.props, { radius: this.isOpen ? this.openRadius : this.radius }, 1000, 'easeOutExpo', () => {
            this.needsUpdate = false;
            this.animatedIn = true;
        });

        this.clearTween().tween({ opacity: 1 }, 400, 'easeOutCubic');
    }

    animateOut() {
        this.animatedIn = false;

        this.clearTween().tween({ opacity: 0 }, 400, 'easeOutCubic');
    }

    destroy() {
        this.removeListeners();

        clearTween(this.props);

        return super.destroy();
    }
}

/**
 * @author pschroen / https://ufo.ai/
 */


class MuteButton extends Interface {
    constructor({
        sound,
        callback
    }) {
        super('.button');

        this.sound = sound;
        this.callback = callback;

        this.width = 24;
        this.height = 16;
        this.animatedIn = false;
        this.needsUpdate = false;

        this.props = {
            yMultiplier: this.sound ? 1 : 0,
            progress: 0
        };

        this.init();
        this.initCanvas();
        this.setSound(this.sound);

        this.addListeners();
    }

    init() {
        this.css({
            position: 'relative',
            width: this.width + 20,
            height: this.height + 20,
            cursor: 'pointer',
            pointerEvents: 'auto',
            webkitUserSelect: 'none',
            userSelect: 'none',
            opacity: 0
        });
    }

    initCanvas() {
        this.canvas = new Interface(null, 'canvas');
        this.canvas.css({
            position: 'absolute',
            left: '50%',
            top: '50%',
            marginLeft: -this.width / 2,
            marginTop: -this.height / 2
        });
        this.context = this.canvas.element.getContext('2d');
        this.add(this.canvas);
    }

    addListeners() {
        this.element.addEventListener('mouseenter', this.onHover);
        this.element.addEventListener('mouseleave', this.onHover);
        this.element.addEventListener('click', this.onClick);
    }

    removeListeners() {
        this.element.removeEventListener('mouseenter', this.onHover);
        this.element.removeEventListener('mouseleave', this.onHover);
        this.element.removeEventListener('click', this.onClick);
    }

    // Event handlers

    onHover = e => {
        if (!this.animatedIn) {
            return;
        }

        clearTween(this.props);

        this.needsUpdate = true;

        if (e.type === 'mouseenter') {
            tween(this.props, { yMultiplier: this.sound ? 0.7 : 0.3 }, 275, 'easeInOutCubic', () => {
                this.needsUpdate = false;
            });
        } else {
            tween(this.props, { yMultiplier: this.sound ? 1 : 0 }, 275, 'easeInOutCubic', () => {
                this.needsUpdate = false;
            });
        }

        this.events.emit('hover', e, { target: this });
    };

    onClick = e => {
        clearTween(this.props);

        if (this.sound) {
            this.sound = false;

            this.needsUpdate = true;

            tween(this.props, { yMultiplier: 0 }, 300, 'easeOutCubic', () => {
                this.needsUpdate = false;
            });
        } else {
            this.sound = true;

            this.needsUpdate = true;

            tween(this.props, { yMultiplier: 1 }, 300, 'easeOutCubic', () => {
                this.needsUpdate = false;
            });
        }

        this.setSound(this.sound);

        this.events.emit('click', e, { target: this });
    };

    // Public methods

    setSound(sound) {
        this.events.emit('update', { sound, target: this });

        if (this.callback) {
            this.callback(sound, this);
        }
    }

    resize() {
        const dpr = 2; // Always 2

        this.canvas.element.width = Math.round(this.width * dpr);
        this.canvas.element.height = Math.round(this.height * dpr);
        this.canvas.element.style.width = `${this.width}px`;
        this.canvas.element.style.height = `${this.height}px`;
        this.context.scale(dpr, dpr);

        // Context properties need to be reassigned after resize
        this.context.lineWidth = 1.5;
        this.context.strokeStyle = Stage.rootStyle.getPropertyValue('--ui-color').trim();

        this.update();
    }

    update() {
        const width = this.width + 2;
        const height = this.height / 2;
        const progress = width * this.props.progress;
        const increase = 90 / 180 * Math.PI / (height / 2);

        this.context.clearRect(0, 0, this.canvas.element.width, this.canvas.element.height);
        this.context.beginPath();

        let counter = 0;
        let x = 0;
        let y = height;

        for (let i = -4; i < width; i++) {
            if (progress >= i) {
                this.context.moveTo(x, y);

                x = i;
                y = height - Math.sin(counter) * (height - 1) * this.props.yMultiplier;
                counter += increase;

                this.context.lineTo(x, y);
            }
        }

        this.context.stroke();
    }

    animateIn() {
        clearTween(this.props);

        this.props.yMultiplier = this.sound ? 1 : 0;
        this.props.progress = 0;

        this.animatedIn = false;
        this.needsUpdate = true;

        tween(this.props, { progress: 1 }, 1000, 'easeOutExpo', () => {
            this.needsUpdate = false;
            this.animatedIn = true;
        });

        this.clearTween().tween({ opacity: 1 }, 400, 'easeOutCubic');
    }

    animateOut() {
        this.animatedIn = false;

        this.clearTween().tween({ opacity: 0 }, 400, 'easeOutCubic');
    }

    destroy() {
        this.removeListeners();

        clearTween(this.props);

        return super.destroy();
    }
}

/**
 * @author pschroen / https://ufo.ai/
 */


class AudioButtonInfo extends Interface {
    constructor() {
        super('.info');

        this.init();
    }

    init() {
        this.css({
            position: 'absolute',
            left: 0,
            top: 0
        });
    }

    // Event handlers

    onClick = () => {
        open(this.link);
    };

    // Public methods

    setData(data) {
        if (!data) {
            return;
        }

        if (!this.wrapper) {
            this.wrapper = new Interface('.wrapper');
            this.wrapper.css({
                position: 'relative',
                webkitUserSelect: 'none',
                userSelect: 'none'
            });
            this.add(this.wrapper);
        }

        const oldWrapper = this.wrapper;
        oldWrapper.element.removeEventListener('click', this.onClick);

        const newWrapper = this.wrapper.clone();

        const name = new Interface('.name');
        name.css({
            fontVariantNumeric: 'tabular-nums',
            lineHeight: 'var(--ui-title-line-height)',
            letterSpacing: 'var(--ui-number-letter-spacing)',
            whiteSpace: 'nowrap'
        });

        if (data.name !== undefined) {
            name.html(data.name);
        }

        const title = new Interface('.title');
        title.css({
            fontSize: 'var(--ui-secondary-font-size)',
            letterSpacing: 'var(--ui-secondary-letter-spacing)',
            color: 'var(--ui-secondary-color)'
        });

        if (data.title !== undefined) {
            title.html(data.title);
        }

        newWrapper.add(name);
        newWrapper.add(title);

        if (data.image) {
            const thumbnail = new Interface('.thumbnail');
            thumbnail.css({
                position: 'absolute',
                left: -40,
                top: 3,
                boxSizing: 'border-box',
                width: 30,
                height: 30,
                border: '1px solid var(--ui-color-divider-line)',
                cursor: 'pointer'
            });
            newWrapper.add(thumbnail);

            const image = new Interface(data.image.cloneNode());
            image.css({
                position: 'absolute',
                left: 0,
                top: 0,
                width: '100%',
                height: '100%',
                objectFit: 'cover'
            });
            thumbnail.add(image);
        }

        if (data.link) {
            newWrapper.css({
                cursor: 'pointer',
                pointerEvents: 'auto'
            });
            newWrapper.element.addEventListener('click', this.onClick);

            this.link = data.link;
        }

        this.tween({ y: -10, opacity: 0 }, 300, 'easeInSine', () => {
            this.replace(oldWrapper, newWrapper);
            this.wrapper = newWrapper;

            oldWrapper.destroy();

            this.css({ y: 10 }).tween({ y: 0, opacity: 1 }, 1000, 'easeOutCubic');
        });
    }
}

